BEGIN;
CREATE SCHEMA IF NOT EXISTS pasabuy_app;
REVOKE ALL ON SCHEMA pasabuy_app FROM PUBLIC, anon, authenticated;
CREATE TABLE IF NOT EXISTS pasabuy_app.users (seq BIGSERIAL UNIQUE, id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, recovery TEXT, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pasabuy_app.sessions (seq BIGSERIAL UNIQUE, token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES pasabuy_app.users(id), expires BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user ON pasabuy_app.sessions(user_id);
CREATE TABLE IF NOT EXISTS pasabuy_app.bookings (seq BIGSERIAL UNIQUE, id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES pasabuy_app.users(id), rider_id TEXT REFERENCES pasabuy_app.users(id), status TEXT NOT NULL CHECK(status IN ('pending','accepted','picked_up','completed','cancelled')), data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS bookings_customer ON pasabuy_app.bookings(customer_id);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_job ON pasabuy_app.bookings(rider_id) WHERE status IN ('accepted','picked_up');
CREATE TABLE IF NOT EXISTS pasabuy_app.listings (seq BIGSERIAL UNIQUE, id TEXT PRIMARY KEY, seller_id TEXT NOT NULL REFERENCES pasabuy_app.users(id), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pasabuy_app.conversations (seq BIGSERIAL UNIQUE, id TEXT PRIMARY KEY, participant_a TEXT NOT NULL REFERENCES pasabuy_app.users(id), participant_b TEXT NOT NULL REFERENCES pasabuy_app.users(id), context TEXT NOT NULL, data TEXT NOT NULL, UNIQUE(participant_a,participant_b,context));
CREATE TABLE IF NOT EXISTS pasabuy_app.notifications (seq BIGSERIAL UNIQUE, id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES pasabuy_app.users(id), data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS notifications_user ON pasabuy_app.notifications(user_id);
CREATE TABLE IF NOT EXISTS pasabuy_app.attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires BIGINT NOT NULL);
ALTER TABLE pasabuy_app.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE pasabuy_app.sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE pasabuy_app.bookings ENABLE ROW LEVEL SECURITY;
ALTER TABLE pasabuy_app.listings ENABLE ROW LEVEL SECURITY;
ALTER TABLE pasabuy_app.conversations ENABLE ROW LEVEL SECURITY;
ALTER TABLE pasabuy_app.notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE pasabuy_app.attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA pasabuy_app FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA pasabuy_app FROM PUBLIC, anon, authenticated;
COMMIT;
